from .ranges import bounds


def serve(data, range_header=None):
    """Serve *data*, honoring *range_header* when given.

    Returns (status, headers, body) as documented in README.md:
      - 200 and the full body when no range header is given;
      - 206 with ``Content-Range: bytes <start>-<end>/<length>`` for a
        satisfied single range (end is inclusive, clamped at EOF);
      - 416 with an empty body and ``Content-Range: bytes */<length>``
        for bad syntax, a start beyond EOF, a zero-length suffix,
        reversed bounds, or empty data.
    """
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    resolved = bounds(range_header, length)
    if resolved is None:
        return (
            416,
            {'Content-Length': '0', 'Content-Range': f'bytes */{length}'},
            b'',
        )
    start, end = resolved
    body = data[start:end + 1]
    return (
        206,
        {'Content-Length': str(len(body)),
         'Content-Range': f'bytes {start}-{end}/{length}'},
        body,
    )
